"use strict";(self.webpackChunkspecmaru=self.webpackChunkspecmaru||[]).push([[25],{25:n=>{n.exports=JSON.parse('[{"id":"2026042001","title":"\uae08 vs \ube44\ud2b8\ucf54\uc778, 2026\ub144\uc5d0\ub294 \ubb34\uc5c7\uc744 \uc120\ud0dd\ud574\uc57c \ud560\uae4c? \uc548\uc815\uc131\uacfc \uc218\uc775\uc131\uc758 \ud604\uc2e4 \ube44\uad50","thumbnail":"/newsimg/26042001.jpg","summary":"\uc804\ud1b5\uc758 \uc548\uc804\uc790\uc0b0 \uae08\uacfc \ub514\uc9c0\ud138 \uc2dc\ub300\uc758 \ub300\ud45c \ud22c\uc790\uc790\uc0b0 \ube44\ud2b8\ucf54\uc778. 2026\ub144 \ud604\uc7ac \uc5b4\ub5a4 \uc790\uc0b0\uc774 \ub354 \uc548\uc815\uc801\uc774\uace0, \uc5b4\ub5a4 \uc790\uc0b0\uc774 \ub354 \ub192\uc740 \uc218\uc775 \uac00\ub2a5\uc131\uc744 \uac00\uc9c8\uae4c\uc694? \uc2e4\uc81c \uae08 \uc2dc\uc138\uc640 \ube44\ud2b8\ucf54\uc778 \uac00\uaca9 \ud750\ub984, \ud22c\uc790 \uc804\ub7b5\uae4c\uc9c0 \ud604\uc2e4\uc801\uc73c\ub85c \ube44\uad50\ud574\ubd05\ub2c8\ub2e4.","sections":"2026\ub144 \ud22c\uc790 \uc2dc\uc7a5\uc5d0\uc11c \uac00\uc7a5 \uc790\uc8fc \ube44\uad50\ub418\ub294 \uc790\uc0b0\uc740 \ub2e8\uc5f0 \uae08\uacfc \ube44\ud2b8\ucf54\uc778\uc785\ub2c8\ub2e4. \uae08\uc740 \uc218\ucc9c \ub144 \ub3d9\uc548 \uac00\uce58 \uc800\uc7a5 \uc218\ub2e8\uc73c\ub85c \uc778\uc815\ubc1b\uc544 \uc628 \ub300\ud45c\uc801\uc778 \uc548\uc804\uc790\uc0b0\uc774\uba70, \ube44\ud2b8\ucf54\uc778\uc740 \ub514\uc9c0\ud138 \uc2dc\ub300\ub97c \ub300\ud45c\ud558\ub294 \uc0c8\ub85c\uc6b4 \ud22c\uc790 \uc790\uc0b0\uc73c\ub85c \ube60\ub974\uac8c \uc790\ub9ac \uc7a1\uc558\uc2b5\ub2c8\ub2e4. \ub450 \uc790\uc0b0\uc740 \uc131\uaca9\uc774 \uc644\uc804\ud788 \ub2e4\ub974\uc9c0\ub9cc, \uacf5\ud1b5\uc801\uc73c\ub85c \uc778\ud50c\ub808\uc774\uc158\uacfc \uae08\uc735 \ubd88\uc548 \uc18d\uc5d0\uc11c \ud22c\uc790\uc790\ub4e4\uc758 \uad00\uc2ec\uc744 \uac15\ud558\uac8c \ubc1b\uace0 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uba3c\uc800 \uae08\uc740 \uc804\ud1b5\uc801\uc778 \uc548\uc804\uc790\uc0b0\uc785\ub2c8\ub2e4. \ud55c\uad6d\uac70\ub798\uc18c(KRX) \uae30\uc900\uc73c\ub85c 2026\ub144 4\uc6d4 \ud604\uc7ac \uad6d\ub0b4 \uae08 1g \uac00\uaca9\uc740 \ub300\ub7b5 219,380\uc6d0 \uc218\uc900\uc5d0\uc11c \uc6c0\uc9c1\uc774\uace0 \uc788\uc73c\uba70, 1\ub3c8(3.75g) \uae30\uc900\uc73c\ub85c\ub294 \uc57d 822,638\uc6d0 \uc218\uc900\uae4c\uc9c0 \ud615\uc131\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uad6d\uc81c \uae08 \uac00\uaca9 \uc5ed\uc2dc \uc628\uc2a4\ub2f9 2,400~2,600\ub2ec\ub7ec \uc218\uc900\uc744 \uc720\uc9c0\ud558\uba70 \uc5ed\uc0ac\uc801\uc73c\ub85c \ub192\uc740 \uad6c\uac04\uc5d0 \uc704\uce58\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uae08\uc740 \uc2e4\ubb3c \uc790\uc0b0\uc774\ub77c\ub294 \uc810\uc5d0\uc11c \uac15\ub825\ud55c \uc2e0\ub8b0\ub97c \uac00\uc9c0\uba70, \uc804\uc7c1, \uacbd\uae30\uce68\uccb4, \uae08\uc735\uc704\uae30, \ub2ec\ub7ec \uc57d\uc138 \uac19\uc740 \ubd88\ud655\uc2e4\uc131\uc774 \ucee4\uc9c8\uc218\ub85d \uac00\uaca9\uc774 \uac15\ud574\uc9c0\ub294 \ud2b9\uc9d5\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc2e4\uc81c\ub85c \uac01\uad6d \uc911\uc559\uc740\ud589\ub4e4\ub3c4 \uc678\ud658\ubcf4\uc720\uace0\uc758 \uc77c\ubd80\ub97c \uae08\uc73c\ub85c \ubcf4\uc720\ud558\uace0 \uc788\uc744 \uc815\ub3c4\ub85c \uc548\uc815\uc131\uc774 \ub192\uc2b5\ub2c8\ub2e4.\\n\\n\ubc18\uba74 \ube44\ud2b8\ucf54\uc778\uc740 \ub514\uc9c0\ud138 \uc2dc\ub300\uc758 \uc0c8\ub85c\uc6b4 \uc790\uc0b0\uc785\ub2c8\ub2e4. 2026\ub144 4\uc6d4 \uae30\uc900 \ube44\ud2b8\ucf54\uc778 \uac00\uaca9\uc740 \ub300\ub7b5 1BTC\ub2f9 8\ub9cc \ub2ec\ub7ec~10\ub9cc \ub2ec\ub7ec \uc218\uc900\uc5d0\uc11c \uac70\ub798\ub418\uace0 \uc788\uc73c\uba70, \uc6d0\ud654 \uae30\uc900\uc73c\ub85c\ub294 \uc57d 1\uc5b5 1\ucc9c\ub9cc \uc6d0\uc5d0\uc11c 1\uc5b5 4\ucc9c\ub9cc \uc6d0 \uc0ac\uc774\ub97c \uc624\uac00\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ube44\ud2b8\ucf54\uc778\uc740 \ucd1d \ubc1c\ud589\ub7c9\uc774 2,100\ub9cc \uac1c\ub85c \uc81c\ud55c\ub418\uc5b4 \uc788\uc5b4 \ud76c\uc18c\uc131\uc774 \ub9e4\uc6b0 \uac15\ud558\uba70, \uc815\ubd80\ub098 \uc911\uc559\uae30\uad00\uc758 \ud1b5\uc81c\ub97c \ubc1b\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc5d0\uc11c \'\ub514\uc9c0\ud138 \uae08\'\uc774\ub77c\ub294 \ubcc4\uba85\uc744 \uac00\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \ucd5c\uadfc \uba87 \ub144\uac04 \ubbf8\uad6d \ud604\ubb3c ETF \uc2b9\uc778\uacfc \ub300\ud615 \uae30\uad00 \ud22c\uc790\uc790\ub4e4\uc758 \uc790\uae08 \uc720\uc785\uc774 \uc774\uc5b4\uc9c0\uba74\uc11c \ub2e8\uc21c\ud55c \ud22c\uae30 \uc790\uc0b0\uc774 \uc544\ub2c8\ub77c \uc7a5\uae30 \ud22c\uc790 \uc790\uc0b0\uc73c\ub85c \uc7ac\ud3c9\uac00\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uc548\uc815\uc131\ub9cc \ub193\uace0 \ubcf4\uba74 \uc5ec\uc804\ud788 \uae08\uc774 \uc6b0\uc704\uc5d0 \uc788\uc2b5\ub2c8\ub2e4. \uae08\uc740 \uc2e4\ubb3c \uc790\uc0b0\uc774\uba70 \uc218\ucc9c \ub144 \ub3d9\uc548 \uac80\uc99d\ub41c \uac00\uce58 \uc800\uc7a5 \uc218\ub2e8\uc785\ub2c8\ub2e4. \uac00\uaca9 \ubcc0\ub3d9\ub3c4 \uc0c1\ub300\uc801\uc73c\ub85c \uc644\ub9cc\ud558\uba70, \uae09\ub77d \uac00\ub2a5\uc131\uc774 \ub0ae\uc2b5\ub2c8\ub2e4. \ubc18\uba74 \ube44\ud2b8\ucf54\uc778\uc740 \ud558\ub8e8\uc5d0\ub3c4 \uc218 \ud37c\uc13c\ud2b8\uc529 \uc6c0\uc9c1\uc774\ub294 \uac15\ud55c \ubcc0\ub3d9\uc131\uc744 \uac00\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc2e4\uc81c\ub85c \uba87 \ub2ec \uc0ac\uc774\uc5d0 \uc218\uc2ed \ud37c\uc13c\ud2b8\uc529 \uc0c1\uc2b9\ud558\uac70\ub098 \ud558\ub77d\ud558\ub294 \uacbd\uc6b0\uac00 \ud754\ud558\uba70, \uac01\uad6d \uc815\ubd80\uc758 \uaddc\uc81c \uc774\uc288\ub098 \uac70\ub798\uc18c \ubb38\uc81c\uc5d0 \ub530\ub77c \uac00\uaca9\uc774 \ud06c\uac8c \ud754\ub4e4\ub9b4 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc6d0\uae08 \ubcf4\uc874\uc774 \uac00\uc7a5 \uc911\uc694\ud55c \ud22c\uc790\uc790\ub77c\uba74 \uae08\uc774 \ud6e8\uc52c \uc548\uc815\uc801\uc778 \uc120\ud0dd\uc774 \ub429\ub2c8\ub2e4.\\n\\n\ud558\uc9c0\ub9cc \uc218\uc775 \uac00\ub2a5\uc131\ub9cc \ubcf8\ub2e4\uba74 \uc774\uc57c\uae30\ub294 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4. \uae08\uc740 \uc790\uc0b0\uc744 \uc9c0\ud0a4\ub294 \uc5ed\ud560\uc5d0 \uac00\uae5d\uc2b5\ub2c8\ub2e4. \ud070 \ud3ed\uc758 \uc0c1\uc2b9\ubcf4\ub2e4\ub294 \uafb8\uc900\ud55c \uac00\uce58 \ubcf4\uc874\uc774 \ud575\uc2ec\uc785\ub2c8\ub2e4. \ubc18\ub300\ub85c \ube44\ud2b8\ucf54\uc778\uc740 \ub192\uc740 \ubcc0\ub3d9\uc131\ub9cc\ud07c \ud070 \uc218\uc775 \uac00\ub2a5\uc131\uc744 \uac00\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc2e4\uc81c\ub85c \uacfc\uac70 \uba87 \ucc28\ub840\uc758 \uc0c1\uc2b9\uc7a5\uc5d0\uc11c\ub294 \uba87 \ubc30 \uc774\uc0c1\uc758 \uc218\uc775\ub960\uc744 \uae30\ub85d\ud558\uae30\ub3c4 \ud588\uc2b5\ub2c8\ub2e4. \ubb3c\ub860 \uadf8\ub9cc\ud07c \ud558\ub77d \uc704\ud5d8\ub3c4 \ud06c\uae30 \ub54c\ubb38\uc5d0 \uacf5\uaca9\uc801\uc778 \ud22c\uc790 \uc131\ud5a5\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n\uadf8\ub798\uc11c \ucd5c\uadfc\uc5d0\ub294 \'\ub458 \uc911 \ud558\ub098\ub97c \uc120\ud0dd\ud558\ub294 \ubc29\uc2dd\'\ubcf4\ub2e4 \'\ub458\uc744 \ud568\uaed8 \uac00\uc838\uac00\ub294 \uc804\ub7b5\'\uc774 \ub354 \ub9ce\uc774 \uc0ac\uc6a9\ub429\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc790\uc0b0\uc758 70%\ub294 \uae08\uc774\ub098 \ub2ec\ub7ec \uac19\uc740 \uc548\uc815 \uc790\uc0b0\uc5d0 \ub450\uace0, \ub098\uba38\uc9c0 30%\ub97c \ube44\ud2b8\ucf54\uc778 \uac19\uc740 \uc131\uc7a5 \uc790\uc0b0\uc5d0 \ubc30\ubd84\ud558\ub294 \ubc29\uc2dd\uc785\ub2c8\ub2e4. \uc774\ub807\uac8c \ud558\uba74 \ud558\ub77d\uc7a5\uc5d0\uc11c\ub294 \ubc29\uc5b4\ub825\uc744 \ud655\ubcf4\ud558\uace0, \uc0c1\uc2b9\uc7a5\uc5d0\uc11c\ub294 \uc218\uc775 \uae30\ud68c\ub97c \uc7a1\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \uc7a5\uae30 \ud22c\uc790 \uad00\uc810\uc5d0\uc11c\ub294 \uc774\ub7f0 \ubd84\uc0b0 \uc804\ub7b5\uc774 \ud6e8\uc52c \ud604\uc2e4\uc801\uc774\ub77c\ub294 \ud3c9\uac00\ub97c \ubc1b\uace0 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uacb0\uad6d \uc911\uc694\ud55c \uac83\uc740 \uc5b4\ub290 \uc790\uc0b0\uc774 \ub354 \uc88b\uc73c\ub0d0\uac00 \uc544\ub2c8\ub77c \uc790\uc2e0\uc758 \ud22c\uc790 \ubaa9\uc801\uc774 \ubb34\uc5c7\uc774\ub0d0\uc785\ub2c8\ub2e4. \uc783\uc9c0 \uc54a\ub294 \uac83\uc774 \uac00\uc7a5 \uc911\uc694\ud558\ub2e4\uba74 \uae08\uc774 \ub354 \uc801\ud569\ud569\ub2c8\ub2e4. \ub192\uc740 \uc218\uc775\uc744 \uac10\uc218\ud558\uace0 \uc131\uc7a5 \uac00\ub2a5\uc131\uc5d0 \ud22c\uc790\ud558\uace0 \uc2f6\ub2e4\uba74 \ube44\ud2b8\ucf54\uc778\uc774 \ub354 \ub9e4\ub825\uc801\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc548\uc815\uc131\uacfc \uc218\uc775\uc131\uc740 \ud56d\uc0c1 \ubc18\ube44\ub840\ud558\uae30 \ub54c\ubb38\uc5d0, \uc790\uc2e0\uc758 \uc131\ud5a5\uc5d0 \ub9de\ub294 \uc120\ud0dd\uc774 \uac00\uc7a5 \uc911\uc694\ud569\ub2c8\ub2e4.\\n\\n2026\ub144\uc5d0\ub3c4 \uae08\uacfc \ube44\ud2b8\ucf54\uc778\uc758 \uacbd\uc7c1\uc740 \uacc4\uc18d\ub420 \uac83\uc785\ub2c8\ub2e4. \uae08\uc740 \uc5ec\uc804\ud788 \uc138\uacc4\uac00 \uc778\uc815\ud558\ub294 \uc548\uc804\uc790\uc0b0\uc774\uace0, \ube44\ud2b8\ucf54\uc778\uc740 \uc0c8\ub85c\uc6b4 \uc2dc\ub300\uc758 \ub514\uc9c0\ud138 \uc790\uc0b0\uc73c\ub85c \uc601\ud5a5\ub825\uc744 \ud655\ub300\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uacb0\uad6d \ud604\uba85\ud55c \ud22c\uc790\uc790\ub294 \uc5b4\ub290 \ud55c\ucabd\ub9cc \ub9f9\uc2e0\ud558\uae30\ubcf4\ub2e4, \ub450 \uc790\uc0b0\uc758 \uc5ed\ud560\uc744 \uc774\ud574\ud558\uace0 \uc790\uc2e0\uc758 \ud3ec\ud2b8\ud3f4\ub9ac\uc624 \uc548\uc5d0\uc11c \uade0\ud615 \uc788\uac8c \ud65c\uc6a9\ud558\ub294 \uc0ac\ub78c\uc77c \uac83\uc785\ub2c8\ub2e4."},{"id":"26022001","title":"\uac24\ub7ed\uc2dc S26 Ultra, 2026\ub144 \uc0bc\uc131\uc758 \uc9c4\uc9dc \uc2b9\ubd80\uc218? \uc2a4\ud399\xb7\ub514\uc790\uc778\xb7\ucd9c\uc2dc \uc804\ub9dd \ucd1d\uc815\ub9ac","thumbnail":"/newsimg/26022001.webp","summary":"\uc0bc\uc131\uc758 \ucc28\uc138\ub300 \ud50c\ub798\uadf8\uc2ed \uc2a4\ub9c8\ud2b8\ud3f0 \uac24\ub7ed\uc2dc S26 Ultra\uac00 2026\ub144 \uac00\uc7a5 \uae30\ub300\ub418\ub294 \uc2a4\ub9c8\ud2b8\ud3f0 \uc911 \ud558\ub098\ub85c \uc8fc\ubaa9\ubc1b\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uce74\uba54\ub77c, \ubc30\ud130\ub9ac, AI \uae30\ub2a5, \ub514\uc790\uc778 \ubcc0\ud654\uae4c\uc9c0 \ud604\uc7ac \uc54c\ub824\uc9c4 \uc815\ubcf4\ub4e4\uc744 \ud604\uc2e4\uc801\uc73c\ub85c \uc815\ub9ac\ud574\ubd05\ub2c8\ub2e4.","sections":"2026\ub144 \uc2a4\ub9c8\ud2b8\ud3f0 \uc2dc\uc7a5\uc5d0\uc11c \uac00\uc7a5 \ud070 \uad00\uc2ec\uc744 \ubc1b\uace0 \uc788\ub294 \uc81c\ud488 \uc911 \ud558\ub098\ub294 \ub2e8\uc5f0 \uac24\ub7ed\uc2dc S26 Ultra\uc785\ub2c8\ub2e4. \uc0bc\uc131\uc740 \ub9e4\ub144 Ultra \ub77c\uc778\uc5c5\uc744 \ud1b5\ud574 \ucd5c\uace0 \uc131\ub2a5\uacfc \ud504\ub9ac\ubbf8\uc5c4 \uae30\ub2a5\uc744 \uc9d1\uc57d\ud55c \ud50c\ub798\uadf8\uc2ed \ubaa8\ub378\uc744 \uc120\ubcf4\uc5ec \uc654\uc73c\uba70, \uc774\ubc88 S26 Ultra \uc5ed\uc2dc \ub2e8\uc21c\ud55c \uc5c5\uadf8\ub808\uc774\ub4dc\uac00 \uc544\ub2cc \uc804\ub7b5\uc801\uc778 \ubcc0\ud654\uac00 \uc608\uc0c1\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 AI \uae30\ub2a5 \uac15\ud654, \uce74\uba54\ub77c \uc13c\uc11c \uac1c\uc120, \ubc30\ud130\ub9ac \ud6a8\uc728 \ud5a5\uc0c1, \uadf8\ub9ac\uace0 \ub514\uc790\uc778 \uc644\uc131\ub3c4\uac00 \ud575\uc2ec \ud3ec\uc778\ud2b8\ub85c \ub5a0\uc624\ub974\uace0 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uc6b0\uc120 \uac00\uc7a5 \ud070 \uad00\uc2ec\uc0ac\ub294 \uce74\uba54\ub77c\uc785\ub2c8\ub2e4. \uac24\ub7ed\uc2dc S25 Ultra\uac00 2\uc5b5 \ud654\uc18c \uba54\uc778 \uce74\uba54\ub77c\ub97c \uc911\uc2ec\uc73c\ub85c \uac15\ub825\ud55c \uc90c \uc131\ub2a5\uc744 \ubcf4\uc5ec\uc92c\ub2e4\uba74, \uac24\ub7ed\uc2dc S26 Ultra\ub294 \ub2e8\uc21c \ud654\uc18c \uacbd\uc7c1\uc774 \uc544\ub2c8\ub77c \uc13c\uc11c \uc790\uccb4\uc758 \ud488\uc9c8 \ud5a5\uc0c1\uc5d0 \uc9d1\uc911\ud560 \uac00\ub2a5\uc131\uc774 \ub192\uc2b5\ub2c8\ub2e4. \uc5c5\uacc4\uc5d0\uc11c\ub294 \uc0c8\ub85c\uc6b4 \ub300\ud615 \uc13c\uc11c \uc801\uc6a9\uacfc \uc800\uc870\ub3c4 \ucd2c\uc601 \uc131\ub2a5 \uac1c\uc120, AI \uae30\ubc18 \uc774\ubbf8\uc9c0 \ud504\ub85c\uc138\uc2f1 \uac15\ud654\uac00 \ud575\uc2ec \ubcc0\ud654\uac00 \ub420 \uac83\uc73c\ub85c \ubcf4\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \uc57c\uac04 \ucd2c\uc601\uacfc \uc778\ubb3c \uc0ac\uc9c4, \uadf8\ub9ac\uace0 \uc601\uc0c1 \ucd2c\uc601 \uc548\uc815\uc131 \ubd80\ubd84\uc5d0\uc11c \ud070 \uac1c\uc120\uc774 \uae30\ub300\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\ubc30\ud130\ub9ac \uc5ed\uc2dc \uc911\uc694\ud55c \ubcc0\ud654 \ud3ec\uc778\ud2b8\uc785\ub2c8\ub2e4. \ucd5c\uadfc \uc2a4\ub9c8\ud2b8\ud3f0 \uc2dc\uc7a5\uc5d0\uc11c\ub294 \ub2e8\uc21c \uc6a9\ub7c9\ubcf4\ub2e4 \uc2e4\uc81c \uc0ac\uc6a9 \uc2dc\uac04\uc774 \ub354 \uc911\uc694\ud574\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uac24\ub7ed\uc2dc S26 Ultra\ub294 \uc57d 5,000mAh \uc218\uc900\uc758 \ubc30\ud130\ub9ac\uc640 \ud568\uaed8 \ucc28\uc138\ub300 \ubc30\ud130\ub9ac \ud6a8\uc728 \uae30\uc220\uc774 \uc801\uc6a9\ub420 \uac00\ub2a5\uc131\uc774 \uac70\ub860\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc5ec\uae30\uc5d0 \ucd5c\uc2e0 \uce69\uc14b\uc758 \uc804\ub825 \ud6a8\uc728\uc774 \ub354\ud574\uc9c0\uba74\uc11c \uc2e4\uc81c \uccb4\uac10 \uc0ac\uc6a9 \uc2dc\uac04\uc740 \ud06c\uac8c \ub298\uc5b4\ub0a0 \uac83\uc73c\ub85c \uc608\uc0c1\ub429\ub2c8\ub2e4. \ube60\ub978 \ucda9\uc804 \uc18d\ub3c4 \uc5ed\uc2dc \uae30\uc874\ubcf4\ub2e4 \ud5a5\uc0c1\ub420 \uac00\ub2a5\uc131\uc774 \ub192\uc544 \uc0ac\uc6a9\uc790 \ub9cc\uc871\ub3c4\ub97c \ub04c\uc5b4\uc62c\ub9b4 \uc694\uc18c\ub85c \ud3c9\uac00\ub429\ub2c8\ub2e4.\\n\\n\ud504\ub85c\uc138\uc11c\ub294 2026\ub144\ud615 \ucd5c\uc2e0 \uce69\uc14b\uc774 \ud0d1\uc7ac\ub420 \uac00\ub2a5\uc131\uc774 \ub9e4\uc6b0 \ub192\uc2b5\ub2c8\ub2e4. \uc9c0\uc5ed\uc5d0 \ub530\ub77c \ud004\ucef4 \uc2a4\ub0c5\ub4dc\ub798\uace4 \ucc28\uc138\ub300 \ud50c\ub798\uadf8\uc2ed \uce69\uc14b\uacfc \uc0bc\uc131 \uc5d1\uc2dc\ub178\uc2a4 \uc2e0\ud615 \uce69\uc14b\uc774 \uc801\uc6a9\ub420 \uac83\uc73c\ub85c \uc608\uc0c1\ub418\uba70, \ud2b9\ud788 AI \uc5f0\uc0b0 \uc131\ub2a5\uc774 \ud06c\uac8c \uac15\ud654\ub420 \uc804\ub9dd\uc785\ub2c8\ub2e4. \uc774\uc81c \uc2a4\ub9c8\ud2b8\ud3f0\uc740 \ub2e8\uc21c\ud788 \ube60\ub978 \uc131\ub2a5\uc774 \uc544\ub2c8\ub77c AI \uae30\ubc18 \uc2e4\uc2dc\uac04 \ubc88\uc5ed, \uc0ac\uc9c4 \uc790\ub3d9 \ud3b8\uc9d1, \ubb38\uc11c \uc694\uc57d, \uc74c\uc131 \ube44\uc11c \uae30\ub2a5 \ub4f1\uc774 \ud575\uc2ec \uacbd\uc7c1\ub825\uc774 \ub418\uace0 \uc788\uae30 \ub54c\ubb38\uc5d0 \uc0bc\uc131 \uc5ed\uc2dc Galaxy AI \uae30\ub2a5\uc744 \ub354\uc6b1 \uacf5\uaca9\uc801\uc73c\ub85c \ud655\uc7a5\ud560 \uac00\ub2a5\uc131\uc774 \ud07d\ub2c8\ub2e4.\\n\\n\ub514\uc790\uc778 \uce21\uba74\uc5d0\uc11c\ub294 \ud070 \ubcc0\ud654\ubcf4\ub2e4\ub294 \uc644\uc131\ub3c4 \uc911\uc2ec\uc758 \uac1c\uc120\uc774 \uc608\uc0c1\ub429\ub2c8\ub2e4. \uae30\uc874\uc758 \uac01\uc9c4 Ultra \ub514\uc790\uc778\uc744 \uc720\uc9c0\ud558\uba74\uc11c\ub3c4 \ub354 \uc587\uc544\uc9c4 \ubca0\uc824, \uac00\ubcbc\uc6cc\uc9c4 \ubb34\uac8c, \uadf8\ub9ac\uace0 \uc190\uc5d0 \uc7a1\ud788\ub294 \uadf8\ub9bd\uac10 \uac1c\uc120\uc774 \ud575\uc2ec\uc774 \ub420 \uac00\ub2a5\uc131\uc774 \ub192\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \ud2f0\ud0c0\ub284 \uc18c\uc7ac \uc801\uc6a9 \ud655\ub300 \uc5ec\ubd80\ub3c4 \ub9ce\uc740 \uad00\uc2ec\uc744 \ubc1b\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ud504\ub9ac\ubbf8\uc5c4 \uc2a4\ub9c8\ud2b8\ud3f0 \uc2dc\uc7a5\uc5d0\uc11c \ub514\uc790\uc778\uc740 \ub2e8\uc21c\ud55c \uc678\ud615\uc774 \uc544\ub2c8\ub77c \ube0c\ub79c\ub4dc \uc774\ubbf8\uc9c0 \uc790\uccb4\ub97c \uacb0\uc815\ud558\uae30 \ub54c\ubb38\uc5d0 \uc0bc\uc131 \uc5ed\uc2dc \uc774 \ubd80\ubd84\uc5d0 \uc0c1\ub2f9\ud55c \ud798\uc744 \uc904 \uac83\uc73c\ub85c \ubcf4\uc785\ub2c8\ub2e4.\\n\\n\ub514\uc2a4\ud50c\ub808\uc774\ub294 \uc5ec\uc804\ud788 \uc0bc\uc131\uc758 \uac00\uc7a5 \uac15\ub825\ud55c \ubb34\uae30\uc785\ub2c8\ub2e4. \uac24\ub7ed\uc2dc S26 Ultra\ub294 6.8\uc778\uce58 \uc774\uc0c1 QHD+ AMOLED \ub514\uc2a4\ud50c\ub808\uc774\uc640 120Hz \uc774\uc0c1\uc758 \uac00\ubcc0 \uc8fc\uc0ac\uc728\uc744 \uc720\uc9c0\ud558\uba74\uc11c \ubc1d\uae30\uc640 \uc0c9 \uc815\ud655\ub3c4\uac00 \ub354\uc6b1 \ud5a5\uc0c1\ub420 \uac83\uc73c\ub85c \uc608\uc0c1\ub429\ub2c8\ub2e4. \ud2b9\ud788 \uc57c\uc678 \uc2dc\uc778\uc131\uacfc \ubc30\ud130\ub9ac \ud6a8\uc728\uc744 \ub3d9\uc2dc\uc5d0 \uc7a1\ub294 LTPO \uae30\uc220 \uac1c\uc120\uc774 \ud575\uc2ec \ud3ec\uc778\ud2b8\uac00 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uac00\uaca9\uc740 \uc5ec\uc804\ud788 \uac00\uc7a5 \ubbfc\uac10\ud55c \ubd80\ubd84\uc785\ub2c8\ub2e4. \uac24\ub7ed\uc2dc S25 Ultra \uc5ed\uc2dc \ub192\uc740 \ucd9c\uace0\uac00\ub85c \ubd80\ub2f4\uc774 \ucef8\ub358 \ub9cc\ud07c, S26 Ultra\ub294 \ud658\uc728\uacfc \ubd80\ud488 \uac00\uaca9 \uc0c1\uc2b9\uc5d0 \ub530\ub77c \uad6d\ub0b4 \ucd9c\uc2dc \uac00\uaca9\uc774 180\ub9cc \uc6d0~220\ub9cc \uc6d0 \uc218\uc900\uae4c\uc9c0 \ud615\uc131\ub420 \uac00\ub2a5\uc131\uc774 \uac70\ub860\ub429\ub2c8\ub2e4. \ud2b9\ud788 \uace0\uc6a9\ub7c9 \ubaa8\ub378\uc740 200\ub9cc \uc6d0\uc744 \ub118\uc5b4\uc124 \uac00\ub2a5\uc131\ub3c4 \uc788\uc5b4 \uc18c\ube44\uc790\ub4e4\uc758 \ubd80\ub2f4\uc740 \ub354\uc6b1 \ucee4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub2e4\ub9cc \uc0ac\uc804\uc608\uc57d \ud61c\ud0dd\uacfc \ubcf4\uc0c1 \ud310\ub9e4 \ud504\ub85c\uadf8\ub7a8\uc774 \uac15\ud654\ub41c\ub2e4\uba74 \uc2e4\uc81c \uccb4\uac10 \uad6c\ub9e4\uac00\ub294 \uc0c1\ub2f9\ud788 \ub0ae\uc544\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\ucd9c\uc2dc\ub294 \uae30\uc874 \ud328\ud134\ub300\ub85c\ub77c\uba74 2026\ub144 1\uc6d4~2\uc6d4 \uc0ac\uc774 \uac24\ub7ed\uc2dc \uc5b8\ud329 \ud589\uc0ac\uc5d0\uc11c \uacf5\uac1c\ub420 \uac00\ub2a5\uc131\uc774 \ub192\uc2b5\ub2c8\ub2e4. \uc0bc\uc131\uc740 \ub9e4\ub144 \ucd08 \ud50c\ub798\uadf8\uc2ed \uacf5\uac1c\ub97c \ud1b5\ud574 \uc0c1\ubc18\uae30 \uc2dc\uc7a5 \uc8fc\ub3c4\uad8c\uc744 \uac00\uc838\uac00\ub294 \uc804\ub7b5\uc744 \uc720\uc9c0\ud574 \uc654\uae30 \ub54c\ubb38\uc5d0 \uc774\ubc88\uc5d0\ub3c4 \uac19\uc740 \ud750\ub984\uc774 \uc774\uc5b4\uc9c8 \uac00\ub2a5\uc131\uc774 \ud07d\ub2c8\ub2e4.\\n\\n\uacb0\uad6d \uac24\ub7ed\uc2dc S26 Ultra\uc758 \ud575\uc2ec\uc740 \'\ud601\uc2e0\'\ubcf4\ub2e4\ub294 \'\uc644\uc131\ub3c4\'\uc5d0 \uc788\uc2b5\ub2c8\ub2e4. \uc2a4\ub9c8\ud2b8\ud3f0 \uc2dc\uc7a5\uc774 \uc131\uc219\uae30\uc5d0 \ub4e4\uc5b4\uc120 \uc9c0\uae08, \uc18c\ube44\uc790\ub4e4\uc740 \ub2e8\uc21c\ud55c \uc22b\uc790 \uacbd\uc7c1\ubcf4\ub2e4 \uc2e4\uc81c \uc0ac\uc6a9 \uacbd\ud5d8\uc758 \ucc28\uc774\ub97c \ub354 \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud569\ub2c8\ub2e4. \uce74\uba54\ub77c\uac00 \uc5bc\ub9c8\ub098 \uc790\uc5f0\uc2a4\ub7ec\uc6b4\uc9c0, \ubc30\ud130\ub9ac\uac00 \uc5bc\ub9c8\ub098 \uc624\ub798 \uac00\ub294\uc9c0, AI \uae30\ub2a5\uc774 \uc2e4\uc81c\ub85c \uc5bc\ub9c8\ub098 \ud3b8\ud55c\uc9c0\uac00 \uad6c\ub9e4\ub97c \uacb0\uc815\ud569\ub2c8\ub2e4.\\n\\n2026\ub144\uc5d0\ub3c4 \uc0bc\uc131\uacfc \uc560\ud50c\uc758 \ud50c\ub798\uadf8\uc2ed \uacbd\uc7c1\uc740 \uacc4\uc18d\ub420 \uac83\uc785\ub2c8\ub2e4. \uac24\ub7ed\uc2dc S26 Ultra\ub294 \ub2e8\uc21c\ud55c \uc2e0\uc81c\ud488\uc774 \uc544\ub2c8\ub77c \uc0bc\uc131 \ud504\ub9ac\ubbf8\uc5c4 \uc804\ub7b5\uc758 \uc911\uc2ec\uc774\uba70, \uc544\uc774\ud3f0 17 Pro Max\uc640\uc758 \uc815\uba74 \uc2b9\ubd80\uac00 \uc608\uc0c1\ub429\ub2c8\ub2e4. \uacb0\uad6d \uc2b9\uc790\ub294 \uc2a4\ud399\ud45c\uac00 \uc544\ub2c8\ub77c \uc2e4\uc81c \uc0ac\uc6a9\uc790 \uacbd\ud5d8\uc5d0\uc11c \uacb0\uc815\ub420 \uac83\uc785\ub2c8\ub2e4."}]')}}]);